DO $$ BEGIN
IF (SELECT count(*) FROM calculation_rules r LEFT JOIN source_sections s ON s.id=r.source_section_id
 WHERE r.module='TAM_THE' AND r.rule_code='TT-TAI-LOC' AND r.rule_version='1.0' AND r.external_source_id IS NULL AND (
