 (r.verification_status='VERIFIED' AND r.description='D02: invert printed stem/month wealth table PDF41; preserve all matches in column order and explicit missing keys; passages PDF41-42.' AND r.reviewer='Codex D02 review 2026-10-25 (same-tool second pass)'
 AND r.reviewed_at IS NOT NULL AND r.verification_note='D02 2026-10-25; two visual passes by the same Codex, not independent human review. Normalized spacing/punctuation; original archaic words retained. Scope=source table and selected transcription, not empirical validity. docs/29-D02-TAM-THE-DATA.md. 120 printed incidences, 12 passages; only 60/120 stem-month keys present, two ordered results per matched key. BAt/BOI and BICH/BINH labels retained, linked by ordinal: DEC-20261025-D02-EDITORIAL. One partially damaged word in HUONG LOC is rendered [CHU_MO], not reconstructed.'
 AND s.source_book_id=(SELECT id FROM source_books WHERE title='Diễn Cầm Tam Thế Diễn Nghĩa' AND edition='Bản PDF scan người dùng cung cấp; chưa xác minh ấn bản in') AND s.section_label='D02-TT-P041' AND s.pdf_page=41 AND s.printed_page_label='42')))<>1
 THEN RAISE EXCEPTION 'D02 protected rule changed'; END IF; END $$;
DO $$ BEGIN
