 AND s.section_label='TT-GIO-SINH' AND s.pdf_page=12 AND s.source_book_id=(SELECT id FROM source_books WHERE title='Diễn Cầm Tam Thế Diễn Nghĩa' AND edition='Bản PDF scan người dùng cung cấp; chưa xác minh ấn bản in')
 AND s.printed_page_label='13' AND (((a.verification_status='SOURCE_LOCATED' AND a.reviewer IS NULL AND a.reviewed_at IS NULL AND a.verification_note IS NULL) OR (a.verification_status='VERIFIED' AND a.reviewer='Codex D02 review 2026-10-25 (same-tool second pass)' AND a.reviewed_at IS NOT NULL AND a.verification_note='D02 2026-10-25; two visual passes by the same Codex, not independent human review. Normalized spacing/punctuation; original archaic words retained. Scope=source table and selected transcription, not empirical validity. docs/29-D02-TAM-THE-DATA.md. Anchor month=1; complete day/night sequence PDF=12; D02 2026-10-25; two visual passes by the same Codex, not independent human review. Normalized spacing/punctuation; original archaic words retained. Scope=source table and selected transcription, not empirical validity. docs/29-D02-TAM-THE-DATA.md. 12 anchors and day/night sequences PDF12-15 reviewed. Owner/TV2 month5 DAU->DAN approval retained. Month11 night first end printed 5:30, adopted 5:39 for continuous two-hour slots; DEC-20261025-D02-HOUR-PARTS records this editorial correction, not a publisher erratum.'))))<>1
